// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Interface describing `dlansp`.
*/
interface Routine {
	/**
	* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix stored in packed form.
	*
	* @param order - storage layout of `AP`
	* @param norm - specifies the norm type
	* @param uplo - specifies whether the upper or lower triangular part of `A` is supplied
	* @param N - order of the matrix `A`
	* @param AP - packed form of a symmetric matrix `A`
	* @returns matrix norm
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );
	*
	* var v = dlansp( 'column-major', 'M', 'upper', 2, AP );
	* // returns 5.0
	*/
	( order: Layout, norm: string, uplo: string, N: number, AP: Float64Array ): number;

	/**
	* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix stored in packed form using alternative indexing semantics.
	*
	* @param order - storage layout of `AP`
	* @param norm - specifies the norm type
	* @param uplo - specifies whether the upper or lower triangular part of `A` is supplied
	* @param N - order of the matrix `A`
	* @param AP - packed form of a symmetric matrix `A`
	* @param strideAP - `AP` stride length
	* @param offsetAP - starting `AP` index
	* @returns matrix norm
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );
	*
	* var v = dlansp.ndarray( 'column-major', 'M', 'upper', 2, AP, 1, 0 );
	* // returns 5.0
	*/
	ndarray( order: Layout, norm: string, uplo: string, N: number, AP: Float64Array, strideAP: number, offsetAP: number ): number;
}

/**
* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix stored in packed form.
*
* @param order - storage layout of `AP`
* @param norm - specifies the norm type
* @param uplo - specifies whether the upper or lower triangular part of `A` is supplied
* @param N - order of the matrix `A`
* @param AP - packed form of a symmetric matrix `A`
* @returns matrix norm
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );
*
* var v = dlansp( 'column-major', 'M', 'upper', 2, AP );
* // returns 5.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );
*
* var v = dlansp.ndarray( 'column-major', 'M', 'upper', 2, AP, 1, 0 );
* // returns 5.0
*/
declare var dlansp: Routine;


// EXPORTS //

export = dlansp;
